//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Whether this error represents a retryable transient failure.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for the retry after `retry_number` failed attempts,
    /// capped without overflowing.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let exponent = retry_number.saturating_sub(1);
        let mut delay = self.base_delay_ms.min(self.max_delay_ms);
        if delay == 0 {
            return 0;
        }
        if exponent > 63 {
            return self.max_delay_ms;
        }
        for _ in 0..exponent {
            delay = delay.saturating_mul(2).min(self.max_delay_ms);
        }
        delay
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_doubles_and_saturates() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };

        assert_eq!(config.delay_for_retry(1), 10);
        assert_eq!(config.delay_for_retry(2), 20);
        assert_eq!(config.delay_for_retry(3), 25);
        assert_eq!(config.delay_for_retry(4), 25);
    }

    #[test]
    fn retry_numbers_beyond_exponent_width_saturate() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: 1,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(65), u64::MAX);
    }

    #[test]
    fn huge_retry_numbers_do_not_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempt = 0;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= config.max_attempts => {
                return Err(error);
            }
            Err(_) => sleeper.sleep_ms(config.delay_for_retry(attempt)),
        }
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms: 10,
        max_delay_ms: 25,
    }
}

#[test]
fn retries_transient_errors_with_bounded_exponential_delays() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(5), &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(RetryError::Transient("temporary".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
}

#[test]
fn permanent_errors_return_without_retrying() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(5), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_the_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(3), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("still down".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("still down".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}
